package com.universalplatform.integration;
import com.fasterxml.jackson.databind.ObjectMapper; import com.universalplatform.identity.*; import com.universalplatform.questionbank.*; import com.universalplatform.security.*; import java.io.*; import java.nio.charset.StandardCharsets; import java.util.*; import javax.xml.XMLConstants; import javax.xml.parsers.*; import javax.xml.transform.*; import javax.xml.transform.dom.DOMSource; import javax.xml.transform.stream.StreamResult; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.w3c.dom.*;
@Service public class QtiService { private final TenantContext tenants; private final AuthorizationService auth; private final QuestionBankDirectory questions; private final QuestionBankService questionBank; private final ObjectMapper json=new ObjectMapper(); QtiService(TenantContext t,AuthorizationService a,QuestionBankDirectory q,QuestionBankService b){tenants=t;auth=a;questions=q;questionBank=b;}
 @Transactional(readOnly=true) public String exportItem(UUID questionVersionId){auth.require(PermissionKey.INTEROPERABILITY_VIEW);QuestionBankDirectory.QuestionReference q=questions.requireQuestionVersion(questionVersionId);try{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();secure(f);Document d=f.newDocumentBuilder().newDocument();Element root=d.createElementNS("http://www.imsglobal.org/xsd/imsqtiasi_v3p0","assessmentItem");root.setAttribute("identifier",q.questionVersionId().toString());root.setAttribute("title",q.title());root.setAttribute("adaptive","false");root.setAttribute("timeDependent","false");d.appendChild(root);Element body=d.createElement("itemBody");Element p=d.createElement("p");p.setTextContent(q.title());body.appendChild(p);root.appendChild(body);if(q.type()==QuestionType.SINGLE_MCQ){Element response=d.createElement("responseDeclaration");response.setAttribute("identifier","RESPONSE");Element correct=d.createElement("correctResponse");JsonNodeAdapter payload=JsonNodeAdapter.parse(q.payloadJson());String answer=payload.first("correctAnswer","correctOption");if(answer!=null){Element value=d.createElement("value");value.setTextContent(answer);correct.appendChild(value);}response.appendChild(correct);root.insertBefore(response,root.getFirstChild());}Transformer t=TransformerFactory.newInstance().newTransformer();t.setOutputProperty(OutputKeys.ENCODING,"UTF-8");t.setOutputProperty(OutputKeys.INDENT,"yes");StringWriter w=new StringWriter();t.transform(new DOMSource(d),new StreamResult(w));return w.toString();}catch(Exception e){throw new IllegalStateException("QTI export failed",e);}}
 @Transactional public QuestionBankService.QuestionView importItem(String xml){auth.require(PermissionKey.INTEROPERABILITY_MANAGE);if(xml==null||xml.isBlank())throw new IllegalArgumentException("QTI item is required");try{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();secure(f);Document d=f.newDocumentBuilder().parse(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)));Element root=d.getDocumentElement();if(root==null||(!"assessmentItem".equals(root.getLocalName())&&!root.getNodeName().endsWith(":assessmentItem")&&!root.getNodeName().equals("assessmentItem")))throw new IllegalArgumentException("QTI assessmentItem root is required");String title=root.getAttribute("title");NodeList prompts=root.getElementsByTagName("p");String prompt=prompts.getLength()>0?prompts.item(0).getTextContent():title;String payload=json.writeValueAsString(Map.of("prompt",prompt==null?"":prompt.trim(),"source","QTI-3.0"));return questionBank.create(title==null||title.isBlank()?"Imported QTI item":title,QuestionType.SHORT_ANSWER,"medium","en",payload,1,0);}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("Invalid QTI assessmentItem",e);}}
 private static void secure(DocumentBuilderFactory f)throws ParserConfigurationException{f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);f.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd",false);f.setXIncludeAware(false);f.setExpandEntityReferences(false);}
 static final class JsonNodeAdapter{private final Map<?,?> map;private JsonNodeAdapter(Map<?,?> map){this.map=map;}static JsonNodeAdapter parse(String json){try{return new JsonNodeAdapter(new ObjectMapper().readValue(json,Map.class));}catch(Exception e){return new JsonNodeAdapter(Map.of());}}String first(String... keys){for(String k:keys){Object v=map.get(k);if(v!=null)return String.valueOf(v);}return null;}}
}
